    if row < 0 or row >= rows or column < 0 or column >= columns:
      return
    if grid[row][column] != '1':
      return

    grid[row][column] = '0'
    visit(row + 1, column)
    visit(row - 1, column)
    visit(row, column + 1)
    visit(row, column - 1)

