def min_window(s, t):
  if not s or not t:
    return ''

  need = {}
  for character in t:
    need[character] = need.get(character, 0) + 1

  have = {}
  required = len(need)
  formed = 0
  left = 0
  best = None

  for right, character in enumerate(s):
    have[character] = have.get(character, 0) + 1
    if character in need and have[character] == need[character]:
      formed += 1

    while formed == required:
      window = (right - left + 1, left, right)
      if best is None or window[0] < best[0]:
        best = window

      removed = s[left]
      have[removed] -= 1
      if removed in need and have[removed] < need[removed]:
        formed -= 1
      left += 1

  return '' if best is None else s[best[1]:best + 1]

