import heapq

def dijkstra(graph, start):
  distances = {node: float('inf') for node in graph}
  distances[start] = 0
  heap = [(0, start)]

  while heap:
    distance, node = heapq.heappop(heap)
    if distance != distances[node]:
      continue

    for neighbor, weight in graph[node]:
      new_distance = distance + weight
      if new_distance < distances[neighbor]:
        distances[neighbor] = new_distance
        heapq.heappush(heap, (new_distance, neighbor))

  return distances

def connected(nodes, edges, first, second):
  parent = list(range(nodes))
  size = [1] * nodes

  def find(node):
    while node != parent[node]:
      parent[node] = parent[parent[node]]
      node = parent[node]
    return node

  def union(a, b):
    root_a, root_b = find(a), find(b)
    if root_a == root_b:
      return
    if size[root_a] < size[root_b]:
      root_a, root_b = root_b, root_a
    parent[root_b] = root_a
    size[root_a] += size[root_b]

  for a, b in edges:
    union(a, b)

  return find(first) == find(second)

def edit_distance(first, second):
  previous = list(range(len(second) + 1))

  for row in range(1, len(first) + 1):
    current = [row]
    for column in range(1, len(second) + 1):
      if first[row - 1] == second[column - 1]:
        current.append(previous[column - 1])
      else:
        insert = current[column - 1]
        delete = previous[column]
        replace = previous[column - 1]
        current.append(1 + min(insert, delete, replace))
    previous = current

  return previous[-1]

from bisect import bisect_left

def longest_increasing_subsequence(numbers):
  tails = []

  for number in numbers:
    index = bisect_left(tails, number)
    if index == len(tails):
      tails.append(number)
    else:
      tails[index] = number

  return len(tails)

def can_partition(numbers):
  total = sum(numbers)
  if total % 2:
    return False

  target = total // 2
  reachable = {0}

  for number in numbers:
    next_sums = set(reachable)
    for current in reachable:
      if current + number <= target:
        next_sums.add(current + number)
    reachable = next_sums

  return target in reachable

def max_product(numbers):
  if not numbers:
    return 0

  maximum = minimum = best = numbers[0]

  for number in numbers[1:]:
    if number < 0:
      maximum, minimum = minimum, maximum

    maximum = max(number, maximum * number)
    minimum = min(number, minimum * number)
    best = max(best, maximum)

  return best

import heapq

def kth_largest(numbers, k):
  heap = []

  for number in numbers:
    heapq.heappush(heap, number)
    if len(heap) > k:
      heapq.heappop(heap)

  return heap[0]

class Node:
  def **init**(self, key=0, value=0):
    self.key = key
    self.value = value
    self.prev = None
    self.next = None


class LRUCache:
  def **init**(self, capacity):
    self.capacity = capacity
    self.cache = {}
    self.left = Node()
    self.right = Node()
    self.left.next = self.right
    self.right.prev = self.left

  def remove(self, node):
    node.prev.next = node.next
    node.next.prev = node.prev

  def insert(self, node):
    previous = self.right.prev
    previous.next = node
    node.prev = previous
    node.next = self.right
    self.right.prev = node

  def get(self, key):
    if key not in self.cache:
      return -1
    node = self.cache[key]
    self.remove(node)
    self.insert(node)
    return node.value

  def put(self, key, value):
    if key in self.cache:
      self.remove(self.cache[key])

    node = Node(key, value)
    self.cache[key] = node
    self.insert(node)

    if len(self.cache) > self.capacity:
      oldest = self.left.next
      self.remove(oldest)
      del self.cache[oldest.key]
